def queue_legacy_verified_apps(apps, schema_editor):
    database = schema_editor.connection.alias
    Application = apps.get_model("oauth2_provider", "Application")
    ApplicationProfile = apps.get_model("api", "ApplicationProfile")
    VerificationRequest = apps.get_model("api", "ApplicationVerificationRequest")
    GlobalConfig = apps.get_model("api", "GlobalConfig")
    config = GlobalConfig.objects.using(database).first()
    szlg_terms_url = config.terms_of_service_url if config else ""

    for profile in ApplicationProfile.objects.using(database).filter(verified=True).iterator():
        application = Application.objects.using(database).get(pk=profile.application_id)
        logo = profile.logo
        snapshot = {
            "name": application.name,
            "client_type": application.client_type,
            "redirect_uris": application.redirect_uris,
            "owner_id": application.user_id,
            "developer": profile.developer,
            "short_description": profile.short_description,
            "launch_url": profile.launch_url,
            "required_group_keys": profile.required_group_keys or [],
            "logo": getattr(logo, "name", logo) or "",
            "privacy_contact_name": profile.privacy_contact_name,
            "privacy_contact_email": profile.privacy_contact_email,
            "privacy_policy_url": profile.privacy_policy_url,
            "uses_szlg_privacy_policy": profile.uses_szlg_privacy_policy,
            "szlg_privacy_policy_url": (
                "/adatvedelem/" if profile.uses_szlg_privacy_policy else ""
            ),
            "terms_of_service_url": profile.terms_of_service_url,
            "uses_szlg_terms_of_service": profile.uses_szlg_terms_of_service,
            "szlg_terms_of_service_url": (
                szlg_terms_url if profile.uses_szlg_terms_of_service else ""
            ),
        }
        VerificationRequest.objects.using(database).create(
            application_id=application.pk,
            status="legacy_review",
            submitted_snapshot=snapshot,
        )
        ApplicationProfile.objects.using(database).filter(pk=profile.pk).update(
            verified=False
        )


def restore_legacy_verified_apps(apps, schema_editor):
    database = schema_editor.connection.alias
    ApplicationProfile = apps.get_model("api", "ApplicationProfile")
    VerificationRequest = apps.get_model("api", "ApplicationVerificationRequest")
    legacy_requests = VerificationRequest.objects.using(database).filter(
        status="legacy_review"
    )
    for application_id in legacy_requests.values_list("application_id", flat=True):
        ApplicationProfile.objects.using(database).filter(
            application_id=application_id
        ).update(verified=True)
    legacy_requests.delete()


